-- M18 step 1: order_line, its guard, indexes, RLS and privileges (M18 plan §3.1.1, §3.2; ADR-017).
--
--   order_line   one mutable row per line of a table session. The id is generated by the client (M20 references
--                lines created offline). The sale price, VAT rate and price source are frozen at entry. The M19
--                columns (fired_*, voided_*, void_reason) are null in M18, except that M18 voids a draft line with the
--                reason 'entry_removed' ("delete before fire": nothing is ever deleted). state is derived, never written.
--
-- Nobody writes the table directly: no INSERT/UPDATE/DELETE grant for any API role; the rows come from SECURITY DEFINER
-- procedures (steps 4-5). The only select policy names owner and admin: the waiter and the chef read lines through
-- definer functions with fixed shapes (unit_price would trip the role scans 004/059). service_role gets select
-- (lesson 2, pinned in pgTAP 160). M17 already has the unique (tenant_id, id) keys on menu_item and table_session that
-- the composite foreign keys need, so this migration adds none.

create table public.order_line (
  id uuid primary key,
  tenant_id uuid not null default app.tenant_id() references public.tenant (id),
  table_session_id uuid not null,
  menu_item_id uuid not null,
  course public.course not null,
  -- Half portions are 0.5 (PRD 3.2); 1.5 is legal.
  qty numeric(4, 1) not null,
  segue boolean not null default false,
  note text,
  is_shared boolean not null default false,
  -- Sale price, VAT included, and its VAT rate: frozen when the waiter adds the dish (ADR-017).
  unit_price numeric(12, 2) not null,
  vat_rate numeric(5, 2) not null,
  price_source text not null,
  -- The client instant of the last applied write (last write wins), beside the server's own instants.
  client_updated_at timestamptz not null,
  created_at timestamptz not null default now(),
  created_by uuid not null default app.app_user_id(),
  updated_at timestamptz not null default now(),
  updated_by uuid not null default app.app_user_id(),
  -- Written by M19 (fire_course, void_line); M18 only voids drafts with 'entry_removed'.
  fired_at timestamptz,
  fired_by uuid,
  voided_at timestamptz,
  voided_by uuid,
  void_reason text,
  state text generated always as (
    case when voided_at is not null then 'voided' when fired_at is not null then 'fired' else 'draft' end) stored,
  constraint order_line_qty_ck check (qty >= 0.5 and qty <= 99 and qty * 2 = trunc(qty * 2)),
  constraint order_line_note_ck check (note is null or (char_length(note) between 1 and 140 and note !~ '[[:cntrl:]]')),
  constraint order_line_price_ck check (unit_price >= 0 and vat_rate >= 0 and price_source in ('menu', 'push')),
  constraint order_line_fired_ck check ((fired_at is null) = (fired_by is null)),
  constraint order_line_voided_ck check (num_nonnulls(voided_at, voided_by, void_reason) in (0, 3)),
  constraint order_line_void_reason_ck check (void_reason is null or void_reason ~ '^[a-z_]{1,40}$'),
  constraint order_line_tenant_id_id_uq unique (tenant_id, id),
  constraint order_line_session_fkey foreign key (tenant_id, table_session_id)
    references public.table_session (tenant_id, id),
  constraint order_line_menu_item_fkey foreign key (tenant_id, menu_item_id)
    references public.menu_item (tenant_id, id),
  constraint order_line_created_by_fkey foreign key (tenant_id, created_by)
    references public.app_user (tenant_id, id),
  constraint order_line_updated_by_fkey foreign key (tenant_id, updated_by)
    references public.app_user (tenant_id, id),
  constraint order_line_fired_by_fkey foreign key (tenant_id, fired_by)
    references public.app_user (tenant_id, id),
  constraint order_line_voided_by_fkey foreign key (tenant_id, voided_by)
    references public.app_user (tenant_id, id)
);
create index order_line_session_idx on public.order_line (tenant_id, table_session_id, created_at, id);

-- The availability read looks at the live batches of a recipe key only, so history does not slow it (plan §3.9).
create index batch_live_idx on public.batch (tenant_id, recipe_key, use_by) where state in ('fresh', 'open');

-- ---------------------------------------------------------------------------------------------------------------------
-- Guard. Identity, links, the frozen price and the creation facts never change; a voided line is final; a fired line
-- may change only by being voided (M19). M19 replaces this function if it needs more.
create function app.order_line_guard() returns trigger
  language plpgsql
  set search_path = ''
as $$
begin
  if new.id is distinct from old.id
     or new.tenant_id is distinct from old.tenant_id
     or new.table_session_id is distinct from old.table_session_id
     or new.menu_item_id is distinct from old.menu_item_id
     or new.unit_price is distinct from old.unit_price
     or new.vat_rate is distinct from old.vat_rate
     or new.price_source is distinct from old.price_source
     or new.created_at is distinct from old.created_at
     or new.created_by is distinct from old.created_by then
    raise exception 'order_line_immutable' using errcode = 'P0001';
  end if;
  if old.voided_at is not null then
    raise exception 'order_line_voided' using errcode = 'P0001';
  end if;
  if old.fired_at is not null then
    if new.voided_at is null
       or new.fired_at is distinct from old.fired_at
       or new.fired_by is distinct from old.fired_by
       or new.course is distinct from old.course
       or new.qty is distinct from old.qty
       or new.segue is distinct from old.segue
       or new.note is distinct from old.note
       or new.is_shared is distinct from old.is_shared
       or new.client_updated_at is distinct from old.client_updated_at then
      raise exception 'order_line_fired' using errcode = 'P0001';
    end if;
  end if;
  return new;
end
$$;
revoke all on function app.order_line_guard() from public, anon, authenticated, service_role;

create trigger order_line_guard before update on public.order_line
  for each row execute function app.order_line_guard();
create trigger order_line_append_only before delete on public.order_line
  for each row execute function app.append_only();
create trigger order_line_no_truncate before truncate on public.order_line
  for each statement execute function app.append_only_truncate();

-- ---------------------------------------------------------------------------------------------------------------------
alter table public.order_line enable row level security;
revoke all on public.order_line from anon, authenticated, service_role;
grant select on public.order_line to authenticated, service_role;
create policy order_line_select on public.order_line for select to authenticated
  using (tenant_id = (select app.tenant_id()) and (select app.role()) in ('owner', 'admin'));
